// Shared source equations; paired WGSL/GLSL implementations are checked against CPU events.
export const solarWGSL=binding=>`
struct SolarData{values:array<vec4f,27>};@group(0) @binding(${binding}) var<uniform> solarData:SolarData;
struct Source{center:vec3f,velocity:vec3f};
fn solarRadius(i:i32)->f32{return solarData.values[i*3].w;}
fn sourceState(i:i32,past:f32)->Source{let c=solarData.values[i*3].xyz;let u=solarData.values[i*3+1].xyz;let omega=solarData.values[i*3+1].w;if(omega==0.){return Source(c,u);}let a=omega*past;let s=sin(a);let co=cos(a);let turn=cross(solarAxis(),u);let halfSine=sin(a*.5);return Source(c+(turn*(2.*halfSine*halfSine)-u*s)/omega,u*co-turn*s);}
fn sourceCameraState(i:i32,past:f32)->Source{let c=solarData.values[i*3+2].xyz;let u=solarData.values[i*3+1].xyz;let omega=solarData.values[i*3+1].w;if(omega==0.){return Source(c,u);}let a=omega*past;let turn=cross(solarAxis(),u);let hs=sin(a*.5);return Source(c+(turn*(2.*hs*hs)-u*sin(a))/omega,u*cos(a)-turn*sin(a));}
fn sourceLogG(n:vec3f,L:f32,w:vec3f)->f32{let m=dot(w,w);let e=1.+dot(n,w);if(m>=1.||e<=0.){return -80.;}return .5*log(1.-m)-L-log(e);}
fn nearSegment(o:vec3f,d:vec3f,r:f32)->bool{let t=clamp(-dot(o,d)/max(dot(d,d),1e-25),0.,1.);let q=o+t*d;return dot(q,q)<=r*r;}
fn sphereFraction(o:vec3f,d:vec3f,r:f32)->f32{let a=dot(d,d);if(a<1e-25){return 2.;}let b=dot(o,d);let perp=o-d*(b/a);let disc=r*r-dot(perp,perp);if(disc<0.){return 2.;}let c= -b/a;let root=sqrt(disc/a);if(c-root>=0.&&c-root<=1.){return c-root;}if(c+root>=0.&&c+root<=1.){return c+root;}return 2.;}
fn solarStepLimit(q:Ray,h0:f32,v:f32)->f32{var h=h0;if(!solarMode()){return h;}let f=shape(length(q.p));let world=q.p-vec3f(0.,0.,v*q.t);let step=(q.n-vec3f(0.,0.,v*f.x))*h0;let curvature=max(.000001,abs(v*f.y)*(2.+abs(v*(1.-f.x))));for(var i=0;i<9;i++){let rad=solarRadius(i);let speed=length(solarData.values[i*3+1].xyz);if(!nearSegment(world-solarData.values[i*3].xyz,step,rad+.07+speed*(q.t+h0))){continue;}h=min(h,sqrt(max(1e-10,rad*.0002)/curvature));}return h;}
fn solarStep(q:Ray,next:Ray,v:f32)->HullHit{var hit=HullHit(2.,-1);if(!solarMode()){return hit;}let world=q.p-vec3f(0.,0.,v*q.t);let end=next.p-vec3f(0.,0.,v*next.t);for(var i=0;i<9;i++){let radius=solarRadius(i);let speed=length(solarData.values[i*3+1].xyz);if(!nearSegment(world-solarData.values[i*3].xyz,end-world,radius+speed*next.t+.00001)){continue;}let a=sourceState(i,q.t);let b=sourceState(i,next.t);let rel=world-a.center;let fraction=sphereFraction(rel,(end-b.center)-rel,radius);if(fraction<hit.fraction){hit=HullHit(fraction,100+i);}}return hit;}
fn solarSurface(q0:Ray,v:f32,body:i32)->Ray{var q=q0;let source=sourceState(body,q.t);let w=source.velocity-vec3f(0.,0.,v*shape(length(q.p)).x);q.l= -sourceLogG(q.n,q.l,w);q.face=100+body;return q;}
fn refineSolar(q:Ray,h:f32,v:f32,hit:HullHit)->Ray{let body=hit.face-100;var f=hit.fraction;for(var j=0;j<4;j++){let e=advanceRay(q,h*f,v);let source=sourceState(body,e.t);let d=e.p-vec3f(0.,0.,v*e.t)-source.center;let w=e.n+source.velocity-vec3f(0.,0.,v*shape(length(e.p)).x);let den=2.*h*dot(d,w);if(abs(den)>1e-20){f=clamp(f-(dot(d,d)-solarRadius(body)*solarRadius(body))/den,0.,1.);}}return solarSurface(advanceRay(q,h*f,v),v,body);}
fn solarExterior(q0:Ray,v:f32,maxTime:f32,diagram:bool)->Ray{var best=q0;if(!solarMode()){return best;}var bestTime=maxTime;let origin=(q0.p-cameraEye())-vec3f(0.,0.,v*q0.t);for(var i=0;i<9;i++){let rad=solarRadius(i);let at=sourceCameraState(i,select(q0.t,0.,diagram));var u=at.velocity;if(diagram){u=vec3f(0.);}let rel=origin-at.center;let d=q0.n+u;let dd=dot(d,d);var t=max(0.,-dot(rel,d)/dd);let speed=length(u);let limit=(length(rel)+rad)/max(.001,1.-speed);let omega=solarData.values[i*3+1].w;let bound=rad+select(.5*speed*abs(omega)*limit*limit,0.,diagram);let broad=rel+d*t;if(t>maxTime+bound||dot(broad,broad)>bound*bound){continue;}
 for(var j=0;j<4;j++){let state=sourceCameraState(i,select(q0.t+t,0.,diagram));let r=origin+q0.n*t-state.center;var w=q0.n+state.velocity;if(diagram){w=q0.n;}t=max(0.,t-dot(r,w)/dot(w,w));}
 let state=sourceCameraState(i,select(q0.t+t,0.,diagram));let delta=origin+q0.n*t-state.center;var w=q0.n+state.velocity;if(diagram){w=q0.n;}let disc=rad*rad-dot(delta,delta);if(disc<0.){continue;}let root=sqrt(disc/dot(w,w));let closest=t;let inside=length(origin-at.center)<rad;var lo=max(0.,closest-2.*rad/max(.001,1.-speed));var hi=closest;if(inside){lo=closest;hi=closest+2.*rad/max(.001,1.-speed);t=closest+root;}else{t=closest-root;}
 for(var j=0;j<6;j++){let s=sourceCameraState(i,select(q0.t+t,0.,diagram));let r=origin+q0.n*t-s.center;var urel=q0.n+s.velocity;if(diagram){urel=q0.n;}let f=dot(r,r)-rad*rad;if((f>0.)!=inside){lo=t;}else{hi=t;}let den=2.*dot(r,urel);var next=(lo+hi)*.5;if(abs(den)>1e-20){next=t-f/den;}if(next<lo||next>hi){next=(lo+hi)*.5;}if(abs(f)>max(1e-15,rad*rad*1e-6)){t=next;}}
 if(t>1e-7&&t<bestTime){bestTime=t;best=q0;best.t=q0.t+t;best.p=origin+q0.n*t+cameraEye()+vec3f(0.,0.,v*best.t);let emit=sourceCameraState(i,select(best.t,0.,diagram));best.l=select(-sourceLogG(q0.n,q0.l,emit.velocity),0.,diagram);best.face=100+i;}}
 return best;}
fn solarColor(i:i32)->vec3f{if(i==0){return vec3f(1.,.67,.2);}if(i==1){return vec3f(.57,.52,.46);}if(i==2){return vec3f(.92,.73,.4);}if(i==3){return vec3f(.18,.48,.85);}if(i==4){return vec3f(.8,.32,.18);}if(i==5){return vec3f(.8,.65,.48);}if(i==6){return vec3f(.84,.76,.52);}if(i==7){return vec3f(.42,.8,.83);}return vec3f(.21,.39,.9);}
fn solarRadiance(i:i32,point:vec3f,past:f32,v:f32,diagram:bool,viewLocal:vec3f,straight:bool,readable:bool)->vec3f{let at=sourceState(i,select(past,0.,diagram));var normal=normalize(point-vec3f(0.,0.,v*past)-at.center);if(straight){normal=normalize(viewLocal*past-sourceCameraState(i,select(past,0.,diagram)).center);}let n=worldVector(normal);var base=solarColor(i);if(i==3){let land=sin(n.x*4.+n.z*2.)+.6*sin(n.y*7.-n.z*3.)+.3*sin(n.z*13.+n.x*8.);base=mix(base,vec3f(.28,.46,.22),smoothstep(.4,.6,land));}if(i>=5){base*=.8+.2*sin(n.y*60.);}if(i==0){return base*(1.+.12*sin(n.y*57.+n.x*21.));}let sun=sourceState(0,select(past,0.,diagram));let light=max(0.,dot(normal,normalize(sun.center-at.center)));return base*(select(.025,.18,readable)+select(.975,.82,readable)*light);}
`;
export const solarGLSL=()=>`
layout(std140)uniform SolarData{vec4 solarValues[27];};
struct Source{vec3 center;vec3 velocity;};
float solarRadius(int i){return solarValues[i*3].w;}
Source sourceState(int i,float past){vec3 c=solarValues[i*3].xyz,u=solarValues[i*3+1].xyz;float omega=solarValues[i*3+1].w;if(omega==0.)return Source(c,u);float a=omega*past,s=sin(a),co=cos(a),halfSine=sin(a*.5);vec3 turn=cross(solarAxis(),u);return Source(c+(turn*(2.*halfSine*halfSine)-u*s)/omega,u*co-turn*s);}
Source sourceCameraState(int i,float past){vec3 c=solarValues[i*3+2].xyz,u=solarValues[i*3+1].xyz;float omega=solarValues[i*3+1].w;if(omega==0.)return Source(c,u);float a=omega*past,hs=sin(a*.5);vec3 turn=cross(solarAxis(),u);return Source(c+(turn*(2.*hs*hs)-u*sin(a))/omega,u*cos(a)-turn*sin(a));}
float sourceLogG(vec3 n,float L,vec3 w){float m=dot(w,w),e=1.+dot(n,w);if(m>=1.||e<=0.)return -80.;return .5*log(1.-m)-L-log(e);}
bool nearSegment(vec3 o,vec3 d,float r){float t=clamp(-dot(o,d)/max(dot(d,d),1e-25),0.,1.);vec3 q=o+t*d;return dot(q,q)<=r*r;}
float sphereFraction(vec3 o,vec3 d,float r){float a=dot(d,d);if(a<1e-25)return 2.;float b=dot(o,d);vec3 perp=o-d*(b/a);float disc=r*r-dot(perp,perp);if(disc<0.)return 2.;float c=-b/a,root=sqrt(disc/a);if(c-root>=0.&&c-root<=1.)return c-root;if(c+root>=0.&&c+root<=1.)return c+root;return 2.;}
float solarStepLimit(Ray q,float h,float v){if(!solarMode())return h;vec2 f=shape(length(q.p));vec3 worldPoint=q.p-vec3(0.,0.,v*q.t),step=(q.n-vec3(0.,0.,v*f.x))*h;float curvature=max(.000001,abs(v*f.y)*(2.+abs(v*(1.-f.x))));for(int i=0;i<9;i++){float rad=solarRadius(i),speed=length(solarValues[i*3+1].xyz);if(nearSegment(worldPoint-solarValues[i*3].xyz,step,rad+.07+speed*(q.t+h)))h=min(h,sqrt(max(1e-10,rad*.0002)/curvature));}return h;}
HullHit solarStep(Ray q,Ray next,float v){HullHit hit=HullHit(2.,-1);if(!solarMode())return hit;vec3 worldPoint=q.p-vec3(0.,0.,v*q.t),end=next.p-vec3(0.,0.,v*next.t);for(int i=0;i<9;i++){float radius=solarRadius(i),speed=length(solarValues[i*3+1].xyz);if(!nearSegment(worldPoint-solarValues[i*3].xyz,end-worldPoint,radius+speed*next.t+.00001))continue;Source a=sourceState(i,q.t),b=sourceState(i,next.t);vec3 rel=worldPoint-a.center;float f=sphereFraction(rel,(end-b.center)-rel,radius);if(f<hit.fraction)hit=HullHit(f,100+i);}return hit;}
Ray solarSurface(Ray q,float v,int body){Source source=sourceState(body,q.t);vec3 w=source.velocity-vec3(0.,0.,v*shape(length(q.p)).x);q.l=-sourceLogG(q.n,q.l,w);q.face=100+body;return q;}
Ray refineSolar(Ray q,float h,float v,HullHit hit){int body=hit.face-100;float f=hit.fraction;for(int j=0;j<4;j++){Ray e=advanceRay(q,h*f,v);Source source=sourceState(body,e.t);vec3 d=e.p-vec3(0.,0.,v*e.t)-source.center,w=e.n+source.velocity-vec3(0.,0.,v*shape(length(e.p)).x);float den=2.*h*dot(d,w);if(abs(den)>1e-20)f=clamp(f-(dot(d,d)-solarRadius(body)*solarRadius(body))/den,0.,1.);}return solarSurface(advanceRay(q,h*f,v),v,body);}
Ray solarExterior(Ray q,float v,float maxTime,bool diagram){Ray best=q;if(!solarMode())return best;float bestTime=maxTime;vec3 origin=(q.p-cameraEye())-vec3(0.,0.,v*q.t);for(int i=0;i<9;i++){float rad=solarRadius(i);Source at=sourceCameraState(i,diagram?0.:q.t);vec3 u=diagram?vec3(0.):at.velocity,rel=origin-at.center,d=q.n+u;float dd=dot(d,d),t=max(0.,-dot(rel,d)/dd),speed=length(u),limit=(length(rel)+rad)/max(.001,1.-speed),omega=solarValues[i*3+1].w,bound=rad+(diagram?0.:.5*speed*abs(omega)*limit*limit);vec3 broad=rel+d*t;if(t>maxTime+bound||dot(broad,broad)>bound*bound)continue;
for(int j=0;j<4;j++){Source state=sourceCameraState(i,diagram?0.:q.t+t);vec3 r=origin+q.n*t-state.center,w=q.n+(diagram?vec3(0.):state.velocity);t=max(0.,t-dot(r,w)/dot(w,w));}
Source state=sourceCameraState(i,diagram?0.:q.t+t);vec3 delta=origin+q.n*t-state.center,w=q.n+(diagram?vec3(0.):state.velocity);float disc=rad*rad-dot(delta,delta);if(disc<0.)continue;float root=sqrt(disc/dot(w,w)),closest=t;bool inside=length(origin-at.center)<rad;float lo=max(0.,closest-2.*rad/max(.001,1.-speed)),hi=closest;if(inside){lo=closest;hi=closest+2.*rad/max(.001,1.-speed);t=closest+root;}else t=closest-root;
for(int j=0;j<6;j++){Source s=sourceCameraState(i,diagram?0.:q.t+t);vec3 r=origin+q.n*t-s.center,urel=q.n+(diagram?vec3(0.):s.velocity);float f=dot(r,r)-rad*rad;if((f>0.)!=inside)lo=t;else hi=t;float den=2.*dot(r,urel),next=(lo+hi)*.5;if(abs(den)>1e-20)next=t-f/den;if(next<lo||next>hi)next=(lo+hi)*.5;if(abs(f)>max(1e-15,rad*rad*1e-6))t=next;}
if(t>1e-7&&t<bestTime){bestTime=t;best=q;best.t=q.t+t;best.p=origin+q.n*t+cameraEye()+vec3(0.,0.,v*best.t);Source emit=sourceCameraState(i,diagram?0.:best.t);best.l=diagram?0.:-sourceLogG(q.n,q.l,emit.velocity);best.face=100+i;}}return best;}
vec3 solarColor(int i){if(i==0)return vec3(1.,.67,.2);if(i==1)return vec3(.57,.52,.46);if(i==2)return vec3(.92,.73,.4);if(i==3)return vec3(.18,.48,.85);if(i==4)return vec3(.8,.32,.18);if(i==5)return vec3(.8,.65,.48);if(i==6)return vec3(.84,.76,.52);if(i==7)return vec3(.42,.8,.83);return vec3(.21,.39,.9);}
vec3 solarRadiance(int i,vec3 point,float past,float v,bool diagram,vec3 viewLocal,bool straight,bool readable){Source at=sourceState(i,diagram?0.:past);vec3 normal=normalize(point-vec3(0.,0.,v*past)-at.center);if(straight)normal=normalize(viewLocal*past-sourceCameraState(i,diagram?0.:past).center);vec3 n=worldVector(normal),base=solarColor(i);if(i==3){float land=sin(n.x*4.+n.z*2.)+.6*sin(n.y*7.-n.z*3.)+.3*sin(n.z*13.+n.x*8.);base=mix(base,vec3(.28,.46,.22),smoothstep(.4,.6,land));}if(i>=5)base*=.8+.2*sin(n.y*60.);if(i==0)return base*(1.+.12*sin(n.y*57.+n.x*21.));Source sun=sourceState(0,diagram?0.:past);float light=max(0.,dot(normal,normalize(sun.center-at.center)));return base*((readable?.18:.025)+(readable?.82:.975)*light);}
`;
